1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
24	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
25	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
26	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
31	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
32	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
34	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
35	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
36	    @Mapping(target = "bulkSignupWarning", ignore = true)
37	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives an owner's age band from the birth date, computed against the registration date
42	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
43	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
44	     * {@code null} when no birth date is present, so the field is omitted from the response.
45	     */
46	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
47	        if (owner == null || owner.getBirthDate() == null) {
48	            return null;
49	        }
50	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
51	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
52	        if (age < 18) {
53	            return OwnerDto.AgeBandEnum.MINOR;
54	        }
55	        if (age < 65) {
56	            return OwnerDto.AgeBandEnum.ADULT;
57	        }
58	        return OwnerDto.AgeBandEnum.SENIOR;
59	    }
60	
61	    /**
62	     * Derives an owner's duplicate-detection identity key as
63	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
64	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
65	     * telephone, email or household id contributes the empty string in its position.
66	     */
67	    default String formatIdentityKey(Owner owner) {
68	        if (owner == null) {
69	            return null;
70	        }
71	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
72	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
73	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
74	        return telephone + "|" + email + "|" + householdId;
75	    }
76	
77	    /**
78	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
79	     * (non-null and non-blank), otherwise {@code PHONE}.
80	     */
81	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
86	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
87	    }
88	
89	    /**
90	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
91	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
92	     * When the customer code is absent it falls back to resolving the region directly, preferring the
93	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
94	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
95	     * {@code "UNKNOWN"} when neither resolves.
96	     */
97	    default String formatLocality(Owner owner) {
98	        if (owner == null) {
99	            return null;
100	        }
101	        String code = owner.getCustomerCode();
102	        if (code != null) {
103	            int dash = code.indexOf('-');
104	            if (dash > 0) {
105	                return code.substring(0, dash);
106	            }
107	        }
108	        String fromPostcode = regionForPostcode(owner.getPostcode());
109	        if (fromPostcode != null) {
110	            return fromPostcode;
111	        }
112	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
113	            case "Sydney" -> "NSW";
114	            case "Melbourne" -> "VIC";
115	            case "Brisbane" -> "QLD";
116	            default -> "UNKNOWN";
117	        };
118	    }
119	
120	    /**
121	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
122	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
123	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
124	     * so the field is omitted from the response.
125	     */
126	    default String formatTimezone(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        return switch (formatLocality(owner)) {
131	            case "NSW" -> "Australia/Sydney";
132	            case "VIC" -> "Australia/Melbourne";
133	            case "QLD" -> "Australia/Brisbane";
134	            default -> null;
135	        };
136	    }
137	
138	    /**
139	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
140	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
141	     * no known range, signalling that the caller should fall back to the city-to-region table.
142	     */
143	    private String regionForPostcode(String postcode) {
144	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
145	            return null;
146	        }
147	        int value = Integer.parseInt(postcode);
148	        if (value >= 2000 && value <= 2099) {
149	            return "NSW";
150	        }
151	        if (value >= 3000 && value <= 3099) {
152	            return "VIC";
153	        }
154	        if (value >= 4000 && value <= 4099) {
155	            return "QLD";
156	        }
157	        return null;
158	    }
159	
160	    /**
161	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
162	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
163	     * owner's tenure exceeds 365 days.
164	     */
165	    default Integer formatMembershipPoints(Owner owner) {
166	        if (owner == null) {
167	            return null;
168	        }
169	        int points = 0;
170	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
171	        if (hasEmail) {
172	            points += 2;
173	        }
174	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
175	        if (unique) {
176	            points += 1;
177	        }
178	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
179	        if (largeHousehold) {
180	            points += 2;
181	        }
182	        boolean tenured = owner.getRegistrationDate() != null
183	            && owner.getRegistrationDate().plusDays(365).isBefore(LocalDate.now());
184	        if (tenured) {
185	            points += 3;
186	        }
187	        return points;
188	    }
189	
190	    /**
191	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
192	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
193	     */
194	    default Integer formatMembershipLevel(Owner owner) {
195	        if (owner == null) {
196	            return null;
197	        }
198	        int points = formatMembershipPoints(owner);
199	        if (points <= 1) {
200	            return 1;
201	        }
202	        if (points <= 3) {
203	            return 2;
204	        }
205	        if (points <= 5) {
206	            return 3;
207	        }
208	        return 4;
209	    }
210	
211	    /**
212	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
213	     * customer code. Returns {@code null} when the customer code is absent.
214	     */
215	    default Integer formatCheckDigit(Owner owner) {
216	        if (owner == null || owner.getCustomerCode() == null) {
217	            return null;
218	        }
219	        String code = owner.getCustomerCode();
220	        int sum = 0;
221	        boolean dbl = true;
222	        for (int i = code.length() - 1; i >= 0; i--) {
223	            char c = code.charAt(i);
224	            if (c < '0' || c > '9') {
225	                continue;
226	            }
227	            int d = c - '0';
228	            if (dbl) {
229	                d *= 2;
230	                if (d > 9) {
231	                    d -= 9;
232	                }
233	            }
234	            sum += d;
235	            dbl = !dbl;
236	        }
237	        return (10 - (sum % 10)) % 10;
238	    }
239	
240	    /**
241	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
